-- =====================================================
-- 999_insert_message_templates.sql
-- 消息模板预置数据（33 条业务模板）
-- 客户系统执行更新时自动写入；template_code 唯一防重
-- =====================================================
ON DUPLICATE KEY UPDATE `template_name`=VALUES(`template_name`), `content_template`=VALUES(`content_template`), `status`=1;
