INSERT INTO `system_notification_template` (`template_code`,`template_name`,`template_type`,`purpose`,`title_template`,`content_template`,`variables`,`status`,`create_time`) VALUES
('NT-APPROVAL-TODO','审批待办提醒',3,'新审批待办通知审批人','您有新的待办审批：{title}','您有一条新的审批待办，请及时处理。\n\n业务类型：{biz_name}\n单据编号：{biz_no}\n申请事项：{title}\n申请人：{applicant}\n申请时间：{apply_time}\n\n请登录系统进入「统一审批 → 我的待办」处理该审批。','[{"desc": "业务类型", "name": "biz_name"}, {"desc": "单据编号", "name": "biz_no"}, {"desc": "事项标题", "name": "title"}, {"desc": "申请人", "name": "applicant"}, {"desc": "申请时间", "name": "apply_time"}]',1,'2026-08-29 10:54:01'),
('NT-APPROVAL-RESULT','审批结果通知',3,'审批通过/驳回结果通知申请人','您的审批申请已{result}','您的审批申请已处理，结果如下：\n\n业务类型：{biz_name}\n单据编号：{biz_no}\n审批结果：{result}\n审批意见：{comment}\n审批人：{approver}\n处理时间：{process_time}\n\n可登录系统进入「统一审批 → 我发起的」查看详情。','[{"desc": "业务类型", "name": "biz_name"}, {"desc": "单据编号", "name": "biz_no"}, {"desc": "审批结果", "name": "result"}, {"desc": "审批意见", "name": "comment"}, {"desc": "审批人", "name": "approver"}, {"desc": "处理时间", "name": "process_time"}]',1,'2026-08-29 10:54:01'),
('NT-TASK-ASSIGN','任务指派通知',2,'新任务指派给执行人','您有新任务：{title}','您被指派了新任务，请及时查看。\n\n任务名称：{title}\n任务说明：{description}\n发起人：{creator}\n截止时间：{deadline}\n\n请登录系统进入「工作台 → 我的任务」处理。','[{"desc": "任务名称", "name": "title"}, {"desc": "任务说明", "name": "description"}, {"desc": "发起人", "name": "creator"}, {"desc": "截止时间", "name": "deadline"}]',1,'2026-08-29 10:54:01'),
('NT-TASK-URGE','任务催办提醒',2,'任务即将到期或超时催办','任务催办：{title}','任务即将到期/已超时，请尽快完成。\n\n任务名称：{title}\n发起人：{creator}\n截止时间：{deadline}\n当前状态：{status}\n\n请登录系统处理，避免影响整体进度。','[{"desc": "任务名称", "name": "title"}, {"desc": "发起人", "name": "creator"}, {"desc": "截止时间", "name": "deadline"}, {"desc": "当前状态", "name": "status"}]',1,'2026-08-29 10:54:01'),
('NT-ORDER-ASSIGN','工单分配通知',6,'新工单分配给处理人','新工单：{order_no}','您有新的工单待处理，请及时响应。\n\n工单编号：{order_no}\n工单标题：{title}\n工单类型：{order_type}\n优先级：{priority}\n报修人：{reporter}\n创建时间：{create_time}\n\n请登录系统进入工单管理处理。','[{"desc": "工单编号", "name": "order_no"}, {"desc": "工单标题", "name": "title"}, {"desc": "工单类型", "name": "order_type"}, {"desc": "优先级", "name": "priority"}, {"desc": "报修人", "name": "reporter"}, {"desc": "创建时间", "name": "create_time"}]',1,'2026-08-29 10:54:01'),
('NT-ORDER-DONE','工单完成通知',6,'工单处理完成通知','工单已完成：{order_no}','工单已处理完成，感谢您的支持。\n\n工单编号：{order_no}\n工单标题：{title}\n处理人：{handler}\n完成时间：{done_time}\n处理结果：{result}\n\n如有疑问请联系处理人。','[{"desc": "工单编号", "name": "order_no"}, {"desc": "工单标题", "name": "title"}, {"desc": "处理人", "name": "handler"}, {"desc": "完成时间", "name": "done_time"}, {"desc": "处理结果", "name": "result"}]',1,'2026-08-29 10:54:01'),
('NT-ALERT-MAINT','设备维护提醒',4,'设备保养/维护计划提醒','设备维护提醒：{device_name}','设备维护计划提醒：\n\n设备名称：{device_name}\n设备编号：{device_code}\n维护类型：{maint_type}\n计划时间：{plan_time}\n负责人：{owner}\n\n请按时完成维护并做好记录。','[{"desc": "设备名称", "name": "device_name"}, {"desc": "设备编号", "name": "device_code"}, {"desc": "维护类型", "name": "maint_type"}, {"desc": "计划时间", "name": "plan_time"}, {"desc": "负责人", "name": "owner"}]',1,'2026-08-29 10:54:01'),
('NT-ALERT-SAFETY','安全巡检提醒',4,'安全检查计划执行提醒','安全巡检提醒：{plan_name}','安全检查计划执行提醒：\n\n检查计划：{plan_name}\n检查类型：{check_type}\n检查区域：{area}\n计划时间：{plan_time}\n负责人：{owner}\n\n请按时完成巡检，发现隐患及时上报。','[{"desc": "检查计划", "name": "plan_name"}, {"desc": "检查类型", "name": "check_type"}, {"desc": "检查区域", "name": "area"}, {"desc": "计划时间", "name": "plan_time"}, {"desc": "负责人", "name": "owner"}]',1,'2026-08-29 10:54:01'),
('NT-ALERT-CONTRACT','合同到期提醒',4,'合同即将到期续签提醒','合同即将到期：{contract_no}','合同即将到期，请及时处理续签：\n\n合同编号：{contract_no}\n合同名称：{title}\n合同方：{party}\n签订日期：{sign_date}\n到期时间：{expire_date}\n\n请登录系统进入「经营管理 → 合同管理」处理。','[{"desc": "合同编号", "name": "contract_no"}, {"desc": "合同名称", "name": "title"}, {"desc": "合同方", "name": "party"}, {"desc": "签订日期", "name": "sign_date"}, {"desc": "到期时间", "name": "expire_date"}]',1,'2026-08-29 10:54:01'),
('NT-ALERT-PURCHASE','采购逾期提醒',4,'采购到货逾期跟进提醒','采购单逾期提醒：{order_no}','采购订单已逾期未到货，请跟进：\n\n采购单号：{order_no}\n采购标题：{title}\n供应商：{supplier}\n预计到货：{expect_date}\n采购员：{buyer}\n\n请及时联系供应商确认进度。','[{"desc": "采购单号", "name": "order_no"}, {"desc": "采购标题", "name": "title"}, {"desc": "供应商", "name": "supplier"}, {"desc": "预计到货", "name": "expect_date"}, {"desc": "采购员", "name": "buyer"}]',1,'2026-08-29 10:54:01'),
('NT-SYS-UPDATE','系统更新通知',1,'系统有新版本提醒更新','系统有新版本 v{version}','系统已发布新版本，请及时更新。\n\n新版本：v{version}\n发布时间：{publish_time}\n\n更新内容：\n{changelog}\n\n请前往「系统维护 → 系统更新」执行更新。更新前系统会自动备份，更新失败自动回滚。','[{"desc": "版本号", "name": "version"}, {"desc": "发布时间", "name": "publish_time"}, {"desc": "更新内容", "name": "changelog"}]',1,'2026-08-29 10:54:01'),
('NT-SYS-PWD','密码变更提醒',1,'登录密码修改安全提醒','您的登录密码已修改','安全提醒：您的登录密码已修改。\n\n账号：{username}\n修改时间：{time}\n修改IP：{ip}\n\n如非本人操作，请立即联系管理员处理。','[{"desc": "账号", "name": "username"}, {"desc": "修改时间", "name": "time"}, {"desc": "修改IP", "name": "ip"}]',1,'2026-08-29 10:54:01'),
('NT-TRAIN-REMIND','培训通知',5,'培训安排通知参训人员','培训通知：{train_name}','您有一场培训安排，请准时参加。\n\n培训主题：{train_name}\n培训讲师：{trainer}\n培训时间：{train_time}\n培训地点：{location}\n\n请提前安排好工作，准时参加。','[{"desc": "培训主题", "name": "train_name"}, {"desc": "培训讲师", "name": "trainer"}, {"desc": "培训时间", "name": "train_time"}, {"desc": "培训地点", "name": "location"}]',1,'2026-08-29 10:54:01'),
('NT-TRAIN-CERT','证书到期提醒',5,'证书到期复审提醒','证书到期提醒：{cert_name}','证书即将到期，请及时复审：\n\n证书名称：{cert_name}\n证书编号：{cert_no}\n持证人：{holder}\n发证日期：{issue_date}\n到期时间：{expire_date}\n\n请提前安排复审，避免证书过期影响业务。','[{"desc": "证书名称", "name": "cert_name"}, {"desc": "证书编号", "name": "cert_no"}, {"desc": "持证人", "name": "holder"}, {"desc": "发证日期", "name": "issue_date"}, {"desc": "到期时间", "name": "expire_date"}]',1,'2026-08-29 10:54:01'),
('NT-ORDER-REJECT','工单驳回通知',6,'维修/工单被驳回通知处理人','工单被驳回：{order_no}','您的工单已被驳回，请查看原因并修改后重新提交。\n\n工单编号：{order_no}\n工单标题：{title}\n驳回原因：{reject_reason}\n驳回人：{operator}\n\n请登录系统进入工单管理查看并处理。','[{"desc": "工单编号", "name": "order_no"}, {"desc": "工单标题", "name": "title"}, {"desc": "驳回原因", "name": "reject_reason"}, {"desc": "驳回人", "name": "operator"}]',1,'2026-08-29 11:46:36'),
('NT-SAFETY-HAZARD','隐患整改指派',4,'安全隐患整改任务指派','隐患整改任务：{hazard_no}','您被指派隐患整改任务，请及时处理。\n\n隐患编号：{hazard_no}\n隐患描述：{description}\n隐患等级：{level}\n整改期限：{deadline}\n指派时间：{assign_time}\n\n请登录系统进入「安全管理 → 隐患整改」处理。','[{"desc": "隐患编号", "name": "hazard_no"}, {"desc": "隐患描述", "name": "description"}, {"desc": "隐患等级", "name": "level"}, {"desc": "整改期限", "name": "deadline"}, {"desc": "指派时间", "name": "assign_time"}]',1,'2026-08-29 11:46:36'),
('NT-SAFETY-HAZARD-REJECT','隐患整改驳回',4,'隐患整改验证驳回通知','隐患整改被驳回：{hazard_no}','您的隐患整改结果被驳回，请重新整改。\n\n隐患编号：{hazard_no}\n驳回原因：{reject_reason}\n验证人：{verifier}\n\n请登录系统重新整改并提交验证。','[{"desc": "隐患编号", "name": "hazard_no"}, {"desc": "驳回原因", "name": "reject_reason"}, {"desc": "验证人", "name": "verifier"}]',1,'2026-08-29 11:46:36'),
('NT-SAFETY-ACCIDENT','事故上报通知',4,'新的事故上报提醒负责人','新的事故上报：{accident_no}','有新的安全事故上报，请及时处理。\n\n事故编号：{accident_no}\n事故类型：{accident_type}\n发生时间：{occur_time}\n上报人：{reporter}\n简要描述：{description}\n\n请登录系统进入事故管理处理。','[{"desc": "事故编号", "name": "accident_no"}, {"desc": "事故类型", "name": "accident_type"}, {"desc": "发生时间", "name": "occur_time"}, {"desc": "上报人", "name": "reporter"}, {"desc": "描述", "name": "description"}]',1,'2026-08-29 11:46:36'),
('NT-SAFETY-CHECK-OVERDUE','检查任务逾期提醒',4,'安全检查任务到期/逾期提醒','检查任务逾期提醒：{task_no}','安全检查任务即将到期或已逾期，请尽快完成。\n\n任务编号：{task_no}\n检查计划：{plan_name}\n到期时间：{deadline}\n负责人：{owner}\n\n请登录系统进入安全检查任务处理。','[{"desc": "任务编号", "name": "task_no"}, {"desc": "检查计划", "name": "plan_name"}, {"desc": "到期时间", "name": "deadline"}, {"desc": "负责人", "name": "owner"}]',1,'2026-08-29 11:46:36'),
('NT-SAFETY-RISK','风险复评提醒',4,'安全风险定期复评提醒','风险复评提醒：{risk_name}','安全风险需要定期复评，请及时安排。\n\n风险名称：{risk_name}\n风险等级：{risk_level}\n上次评估：{last_review}\n复评期限：{deadline}\n\n请登录系统进入风险管控处理。','[{"desc": "风险名称", "name": "risk_name"}, {"desc": "风险等级", "name": "risk_level"}, {"desc": "上次评估", "name": "last_review"}, {"desc": "复评期限", "name": "deadline"}]',1,'2026-08-29 11:46:36'),
('NT-WAREHOUSE-PLAN','盘点任务分配',2,'库存盘点任务分配通知','盘点任务已分配：{plan_name}','您被分配了盘点任务，请及时执行。\n\n盘点计划：{plan_name}\n盘点仓库：{warehouse}\n盘点方式：{check_type}\n计划日期：{plan_date}\n参与人员：{members}\n\n请登录系统进入「仓储管理 → 盘点执行」处理。','[{"desc": "盘点计划", "name": "plan_name"}, {"desc": "盘点仓库", "name": "warehouse"}, {"desc": "盘点方式", "name": "check_type"}, {"desc": "计划日期", "name": "plan_date"}, {"desc": "参与人员", "name": "members"}]',1,'2026-08-29 11:46:36'),
('NT-WAREHOUSE-DIFF','盘点差异处理',2,'盘点差异处理完成通知','盘点差异已处理：{diff_no}','盘点差异已处理完成，结果如下。\n\n差异编号：{diff_no}\n盘点计划：{plan_name}\n差异类型：{diff_type}\n差异数量：{diff_count}\n处理方式：{handle_type}\n\n请登录系统查看差异明细。','[{"desc": "差异编号", "name": "diff_no"}, {"desc": "盘点计划", "name": "plan_name"}, {"desc": "差异类型", "name": "diff_type"}, {"desc": "差异数量", "name": "diff_count"}, {"desc": "处理方式", "name": "handle_type"}]',1,'2026-08-29 11:46:36'),
('NT-BUSINESS-SHIP','发货通知',6,'销售发货单通知','发货通知：{ship_no}','您的销售订单已安排发货，请查收。\n\n发货单号：{ship_no}\n销售订单：{order_no}\n客户：{customer}\n物流公司：{logistics}\n物流单号：{tracking_no}\n发货日期：{ship_date}\n\n请登录系统查看发货详情。','[{"desc": "发货单号", "name": "ship_no"}, {"desc": "销售订单", "name": "order_no"}, {"desc": "客户", "name": "customer"}, {"desc": "物流公司", "name": "logistics"}, {"desc": "物流单号", "name": "tracking_no"}, {"desc": "发货日期", "name": "ship_date"}]',1,'2026-08-29 11:46:36'),
('NT-PROD-REPORT-REJECT','报工驳回通知',6,'生产报工被驳回通知','报工被驳回：{report_no}','您的生产报工被驳回，请查看原因。\n\n报工编号：{report_no}\n工单号：{work_no}\n驳回原因：{reject_reason}\n驳回人：{operator}\n\n请登录系统重新报工。','[{"desc": "报工编号", "name": "report_no"}, {"desc": "工单号", "name": "work_no"}, {"desc": "驳回原因", "name": "reject_reason"}, {"desc": "驳回人", "name": "operator"}]',1,'2026-08-29 11:46:36'),
('NT-HR-RECRUIT-OFFER','录用通知',1,'招聘录用结果通知','录用通知：{position}','恭喜，您的录用申请已通过！\n\n应聘职位：{position}\n应聘者：{candidate}\n录用状态：{offer_status}\n入职时间：{entry_date}\n\n请登录系统查看录用详情。','[{"desc": "应聘职位", "name": "position"}, {"desc": "应聘者", "name": "candidate"}, {"desc": "录用状态", "name": "offer_status"}, {"desc": "入职时间", "name": "entry_date"}]',1,'2026-08-29 11:46:36'),
('NT-HR-TRANSFER','员工异动通知',1,'员工异动生效通知','员工异动通知：{employee}','您的员工异动已生效，信息如下。\n\n员工：{employee}\n异动类型：{transfer_type}\n原部门/岗位：{from_info}\n新部门/岗位：{to_info}\n生效日期：{effective_date}\n\n请登录系统查看异动详情。','[{"desc": "员工", "name": "employee"}, {"desc": "异动类型", "name": "transfer_type"}, {"desc": "原部门/岗位", "name": "from_info"}, {"desc": "新部门/岗位", "name": "to_info"}, {"desc": "生效日期", "name": "effective_date"}]',1,'2026-08-29 11:46:36'),
('NT-APPROVAL-REVOKE','审批撤销通知',3,'审批申请被撤销通知','审批申请已撤销：{title}','有审批申请被申请人撤销，通知如下。\n\n业务类型：{biz_name}\n单据编号：{biz_no}\n申请事项：{title}\n撤销人：{operator}\n撤销时间：{revoke_time}\n\n请登录系统查看。','[{"desc": "业务类型", "name": "biz_name"}, {"desc": "单据编号", "name": "biz_no"}, {"desc": "申请事项", "name": "title"}, {"desc": "撤销人", "name": "operator"}, {"desc": "撤销时间", "name": "revoke_time"}]',1,'2026-08-29 11:46:36'),
('NT-APPROVAL-PROXY','审批代理通知',3,'审批代理设置/代理任务通知','审批代理：{agent_name}','审批代理设置或代理任务通知，请知悉。\n\n代理人：{agent_name}\n被代理人：{principal}\n代理范围：{scope}\n代理期限：{period}\n\n若为代理审批任务，请登录系统「统一审批 → 我的待办」处理。','[{"desc": "代理人", "name": "agent_name"}, {"desc": "被代理人", "name": "principal"}, {"desc": "代理范围", "name": "scope"}, {"desc": "代理期限", "name": "period"}]',1,'2026-08-29 11:46:36'),
('NT-SYS-LOGIN','异地登录提醒',1,'账号异地登录安全提醒','异地登录提醒','您的账号在异地登录，请注意账号安全。\n\n账号：{username}\n登录IP：{ip}\n登录时间：{time}\n登录地点：{location}\n\n如非本人操作，请立即修改密码并联系管理员。','[{"desc": "账号", "name": "username"}, {"desc": "登录IP", "name": "ip"}, {"desc": "登录时间", "name": "time"}, {"desc": "登录地点", "name": "location"}]',1,'2026-08-29 11:46:36'),
('NT-ALERT-ANNUAL','设备年检提醒',4,'设备年检到期提醒','设备年检提醒：{device_name}','设备年检时间即将到期，请及时安排。\n\n设备名称：{device_name}\n设备编号：{device_code}\n上次年检：{last_check}\n年检期限：{deadline}\n负责人：{owner}\n\n请登录系统安排年检。','[{"desc": "设备名称", "name": "device_name"}, {"desc": "设备编号", "name": "device_code"}, {"desc": "上次年检", "name": "last_check"}, {"desc": "年检期限", "name": "deadline"}, {"desc": "负责人", "name": "owner"}]',1,'2026-08-29 11:46:36'),
('NT-TRAIN-EXAM','考试开始提醒',5,'考试开始通知','考试开始提醒：{exam_name}','您有考试即将开始，请做好准备。\n\n考试名称：{exam_name}\n考试科目：{subject}\n开始时间：{start_time}\n考试时长：{duration}\n考试方式：{exam_mode}\n\n请准时参加考试。','[{"desc": "考试名称", "name": "exam_name"}, {"desc": "考试科目", "name": "subject"}, {"desc": "开始时间", "name": "start_time"}, {"desc": "考试时长", "name": "duration"}, {"desc": "考试方式", "name": "exam_mode"}]',1,'2026-08-29 11:46:36'),
('NT-PROD-DISPATCH','生产派工通知',6,'生产工单派工/排程通知','生产派工通知：{work_no}','您有新的生产工单，请及时处理。\n\n工单号：{work_no}\n产品：{product}\n数量：{quantity}\n派工班组：{team}\n计划完成：{plan_date}\n派工人：{dispatcher}\n\n请登录系统进入生产管理处理。','[{"desc": "工单号", "name": "work_no"}, {"desc": "产品", "name": "product"}, {"desc": "数量", "name": "quantity"}, {"desc": "派工班组", "name": "team"}, {"desc": "计划完成", "name": "plan_date"}, {"desc": "派工人", "name": "dispatcher"}]',1,'2026-08-29 11:47:20'),
('NT-ALERT-MONITOR','系统监控告警',4,'服务器资源超阈值告警','系统监控告警：{metric}','系统监控检测到资源使用异常，请及时处理。\n\n监控指标：{metric}\n当前值：{current_value}\n告警阈值：{threshold}\n服务器IP：{host_ip}\n检测时间：{alarm_time}\n\n请登录系统查看系统监控详情。','[{"desc": "监控指标(CPU/内存/磁盘)", "name": "metric"}, {"desc": "当前值", "name": "current_value"}, {"desc": "告警阈值", "name": "threshold"}, {"desc": "服务器IP", "name": "host_ip"}, {"desc": "检测时间", "name": "alarm_time"}]',1,'2026-08-29 15:21:11')
